#!/bin/sh
# Container start: resolve the API key, refuse to run a production API without
# one, apply database migrations, then hand over to the CMD (uvicorn) as PID 1.
set -e

# No API_KEY given: use the key generated by docker compose (api-key-init).
if [ -z "${API_KEY:-}" ] && [ -r /run/sunrise/api_key ]; then
  API_KEY="$(cat /run/sunrise/api_key)"
  export API_KEY
fi

if [ "${ENVIRONMENT:-production}" = "production" ] && [ -z "${API_KEY:-}" ]; then
  echo "ERROR: API_KEY is empty. Set API_KEY in the .env file next to docker-compose.yml (see .env.example)." >&2
  exit 1
fi

alembic upgrade head
exec "$@"
